const fs=require("fs");
function keypairMetadata(envFile=".env"){return fs.existsSync(envFile)?fs.readFileSync(envFile,"utf8"):null;}
function removeEnvKey(key,keysFilepath=".env.keys"){const p=require("path").resolve(keysFilepath);return fs.readFileSync(p,"utf8");}
module.exports={keypairMetadata,removeEnvKey};
